const CSS=".card{box-sizing:border-box;height:100%;overflow:hidden;color:var(--ink);font-size:12px;line-height:1.35;background:transparent}\n.card *{box-sizing:border-box}\n.card[data-size=\"6x6\"]{font-size:13px}\n.mx{height:100%;display:flex;flex-direction:column;gap:6px;padding:10px;min-height:0;min-width:0}\n.card[data-size=\"3x6\"] .mx,.card[data-size=\"6x6\"] .mx{padding:12px;gap:8px}\n.mx button{font:inherit;cursor:pointer}\n.mx p{margin:0}\n\n.mx-btn{display:inline-flex;align-items:center;justify-content:center;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);border-radius:8px;padding:0 10px;height:28px;font-size:12px;white-space:nowrap}\n.mx-btn.pri{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.mx-btn:disabled{opacity:.5;cursor:default}\n\n.mx-head{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:\"val add\" \"meta meta\";gap:4px 8px;align-items:center;flex:none}\n.mx-val-box{grid-area:val;display:flex;align-items:baseline;gap:3px;min-width:0;flex-wrap:wrap}\n.mx-big{font-size:26px;font-weight:700;line-height:1.05;font-variant-numeric:tabular-nums;white-space:nowrap}\n.mx-of{font-size:12px;color:var(--muted);white-space:nowrap}\n.mx-date{order:3;margin-left:4px;font-size:10.5px;color:var(--muted);white-space:nowrap}\n.mx-meta{grid-area:meta;display:flex;gap:4px;flex-wrap:wrap}\n.mx-chip{font-size:10.5px;padding:1px 7px;border-radius:999px;background:var(--soft);color:var(--ink);white-space:nowrap}\n.mx-chip.mute{color:var(--muted)}\n.mx-chip.ok{background:var(--accent);color:var(--on-accent);font-weight:600}\n.mx-add{grid-area:add}\n.mx-plus{font-size:14px;line-height:1}\n\n.card[data-size=\"3x3\"] .mx-lbl{display:none}\n.card[data-size=\"3x3\"] .mx-add-t{display:none}\n.card[data-size=\"3x3\"] .mx-add{width:30px;padding:0}\n.card[data-size=\"3x6\"] .mx-big,.card[data-size=\"6x6\"] .mx-big{font-size:32px}\n.card[data-size=\"6x6\"] .mx-chip{font-size:11.5px;padding:2px 9px}\n\n.card[data-size=\"6x3\"] .mx.main{flex-direction:row;gap:10px}\n.card[data-size=\"6x3\"] .mx-head{width:116px;flex:none;grid-template-columns:minmax(0,1fr);grid-template-areas:\"val\" \"meta\" \"add\";grid-template-rows:auto auto 1fr;align-content:start}\n.card[data-size=\"6x3\"] .mx-add{align-self:end;width:100%}\n.card[data-size=\"6x3\"] .mx-meta{flex-direction:column;align-items:flex-start}\n.card[data-size=\"6x3\"] .mx-date{order:-1;flex-basis:100%;margin:0}\n\n.mx-main{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.mx-tabs{display:flex;gap:3px;padding:2px;background:var(--soft);border-radius:9px;flex:none}\n.mx-tab{flex:1;border:0;background:transparent;color:var(--muted);height:22px;border-radius:7px;font-size:11.5px;padding:0}\n.mx-tab.on{background:var(--accent);color:var(--on-accent);font-weight:600}\n.mx-body{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:6px}\n.mx-body>*{flex:none}\n\n.mx-step{display:flex;align-items:center;gap:4px;min-height:22px}\n.mx-nav{width:22px;height:22px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);border-radius:6px;padding:0;line-height:1;font-size:14px;display:inline-flex;align-items:center;justify-content:center;flex:none}\n.mx-nav:disabled{opacity:.35;cursor:default}\n.mx-step-l{font-weight:600;font-size:12px;white-space:nowrap}\n.mx-sp{flex:1}\n.mx-rng{border:1px solid var(--line);background:transparent;color:var(--muted);border-radius:999px;height:20px;padding:0 8px;font-size:10.5px;white-space:nowrap}\n.mx-solo{color:var(--muted);font-size:10.5px;white-space:nowrap}\n\n.mx-chartbox{min-width:0}\n.mx-chart{width:100%;height:auto;display:block;overflow:visible}\n.mx-grid{stroke:var(--line);stroke-width:1}\n.mx-ax{fill:var(--muted);font-size:9px}\n.mx-tgt{stroke:var(--accent-alt);stroke-width:1.3;stroke-dasharray:4 3}\n.mx-tl{fill:var(--ink);font-size:9px}\n.mx-area{fill:var(--soft);opacity:.75}\n.mx-line{fill:none;stroke:var(--accent);stroke-width:2;stroke-linejoin:round;stroke-linecap:round}\n.mx-dot{fill:var(--paper);stroke:var(--accent);stroke-width:2}\n.mx-dot.sel{fill:var(--accent)}\n.mx-val{fill:var(--muted);font-size:9.5px}\n.mx-val.sel{fill:var(--ink);font-weight:700}\n.mx-hit{fill:transparent;cursor:pointer}\n\n.mx-cmp,.mx-hint,.mx-note{color:var(--muted);font-size:10.5px}\n.mx-sub{font-weight:700;font-size:12px;margin-top:2px}\n.mx-secs{display:flex;flex-direction:column;gap:7px}\n.mx-sec{display:flex;flex-direction:column;gap:3px}\n.mx-s-top{display:flex;align-items:baseline;gap:6px;min-width:0}\n.mx-s-name{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600}\n.mx-tag{font-size:9.5px;padding:0 5px;border-radius:999px;border:1px solid var(--accent);color:var(--ink);flex:none;white-space:nowrap}\n.mx-tag.weak{border-color:var(--accent-alt)}\n.mx-s-val{flex:none;white-space:nowrap;font-variant-numeric:tabular-nums}\n.mx-pct{display:none;color:var(--muted)}\n.card[data-size^=\"6\"] .mx-pct{display:inline}\n.mx-s-d{flex:none;min-width:30px;text-align:right;white-space:nowrap;font-size:11px;color:var(--muted)}\n.mx-s-d.up{color:var(--ink);font-weight:700}\n.mx-bar{height:6px;border-radius:99px;background:var(--soft);overflow:hidden}\n.mx-fill{display:block;height:100%;background:var(--accent);border-radius:99px}\n.mx-fill.weak{background:var(--accent-alt)}\n.mx-none{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;color:var(--muted);font-size:11px}\n\n.mx-list{display:flex;flex-direction:column;gap:4px}\n.mx-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:1px 8px;align-items:baseline;text-align:left;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);border-radius:9px;padding:6px 8px;width:100%}\n.mx-r-date{color:var(--muted);font-size:11px;white-space:nowrap}\n.mx-r-total{font-weight:700;font-variant-numeric:tabular-nums;white-space:nowrap}\n.mx-r-d{min-width:34px;text-align:right;font-size:11px;color:var(--muted);white-space:nowrap}\n.mx-r-sub{grid-column:1/-1;color:var(--muted);font-size:10.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n\n.mx.empty{justify-content:center}\n.mx-empty{margin:auto;display:flex;flex-direction:column;align-items:center;gap:8px;text-align:center;max-width:300px}\n.mx-e-t{font-size:15px;font-weight:700}\n.mx-e-s{color:var(--muted);font-size:11px}\n.card[data-size] .mx.empty .mx-add{width:auto;padding:0 12px}\n.card[data-size] .mx.empty .mx-add-t{display:inline}\n\n.mx-pbar{display:flex;align-items:center;gap:6px;flex:none}\n.mx-back{width:26px;height:26px;font-size:16px}\n.mx-ptitle{flex:1;min-width:0;font-weight:700;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.mx-pbody{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:8px;padding-right:2px}\n.mx-pbody>*{flex:none}\n.mx-pfoot{flex:none;display:flex;flex-wrap:wrap;gap:6px;align-items:center}\n.mx-pfoot .mx-btn{flex:1}\n.mx-err{flex-basis:100%;font-size:11px;font-weight:600;padding:3px 7px;border-radius:7px;background:var(--soft);color:var(--ink)}\n\n.mx-kv{display:grid;grid-template-columns:1fr 1fr;gap:4px}\n.card[data-size^=\"6\"] .mx-kv{grid-template-columns:repeat(4,minmax(0,1fr))}\n.mx-k{background:var(--soft);border-radius:8px;padding:4px 8px;display:flex;flex-direction:column;min-width:0}\n.mx-k small{color:var(--muted);font-size:10px}\n.mx-k b{font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n\n.mx-form{display:grid;grid-template-columns:1fr 1fr;gap:6px}\n.card[data-size^=\"6\"] .mx-form{grid-template-columns:repeat(4,minmax(0,1fr))}\n.card[data-size^=\"3\"] .f-date,.card[data-size^=\"3\"] .f-full{grid-column:1/-1}\n.mx-f{display:flex;flex-direction:column;gap:2px;min-width:0}\n.f-note{grid-column:1/-1}\n.mx-fl{font-size:10.5px;color:var(--muted)}\n.mx-in{width:100%;min-width:0;height:28px;border:1px solid var(--line);border-radius:7px;background:var(--button-paper,var(--panel-paper));color:var(--ink);padding:0 7px;font:inherit}\n.mx-in::placeholder{color:var(--muted);opacity:.8}\n.mx-sech{display:flex;align-items:center;justify-content:space-between;gap:6px}\n.mx-er{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) 26px;gap:4px;align-items:center}\n.mx-er .nm{grid-column:1/3}\n.mx-x{grid-row:1;grid-column:3;width:26px;height:26px;border:1px solid var(--line);background:transparent;color:var(--muted);border-radius:6px;padding:0;font-size:11px}\n.card[data-size^=\"6\"] .mx-er{grid-template-columns:minmax(0,1.6fr) minmax(0,1fr) minmax(0,1fr) 26px}\n.card[data-size^=\"6\"] .mx-er .nm{grid-column:auto}\n.card[data-size^=\"6\"] .mx-x{grid-row:auto;grid-column:auto}\n.mx-save{flex:1}\n";
function mxNum(v){if(v===null||v===undefined||v==='')return null;const n=Number(v);return isFinite(n)?n:null;}
function mxFmt(n){if(n===null||n===undefined||!isFinite(n))return '—';return String(Math.round(n*100)/100);}
function mxStr(n){return n===null||n===undefined?'':String(n);}
function mxMD(d){const p=String(d).split('-');return p.length===3?(Number(p[1])+'/'+Number(p[2])):String(d);}
function mxH(el){
  return function(tag,attrs){
    const kids=[];
    for(let i=2;i<arguments.length;i++)kids.push(arguments[i]);
    const flat=kids.flat(5).filter(k=>k!==null&&k!==undefined&&k!==false).map(k=>typeof k==='number'?String(k):k);
    return el.apply(null,[tag,attrs||{}].concat(flat));
  };
}
function mxExams(s){
  const a=s&&Array.isArray(s.exams)?s.exams:[];
  const out=[];
  a.forEach((e,i)=>{
    if(!e||!e.id||!e.date)return;
    const total=mxNum(e.total);
    if(total===null)return;
    const secs=(Array.isArray(e.sections)?e.sections:[]).map(x=>({name:String((x&&x.name)||''),score:mxNum(x&&x.score),full:mxNum(x&&x.full)})).filter(x=>x.name&&x.score!==null).map(x=>({name:x.name,score:x.score,full:x.full>0?x.full:null}));
    const fl=mxNum(e.full),tg=mxNum(e.target);
    out.push({id:e.id,date:String(e.date),total:total,full:fl>0?fl:null,target:tg>0?tg:null,sections:secs,note:String(e.note||''),_i:i});
  });
  out.sort((a,b)=>a.date<b.date?-1:a.date>b.date?1:a._i-b._i);
  return out;
}
function mxSel(list,id){
  for(let i=0;i<list.length;i++)if(list[i].id===id)return list[i];
  return list.length?list[list.length-1]:null;
}
function mxPrev(list,id){
  for(let i=0;i<list.length;i++)if(list[i].id===id)return i>0?list[i-1]:null;
  return null;
}
function mxHist(list,name){
  let m=0;
  list.forEach(e=>e.sections.forEach(s=>{if(s.name===name&&s.score>m)m=s.score;}));
  return m;
}
function mxRatio(s,list){
  if(s.full>0)return {r:Math.max(0,Math.min(1,s.score/s.full)),rel:false};
  const m=mxHist(list,s.name);
  return {r:m>0?Math.max(0,Math.min(1,s.score/m)):0,rel:true};
}
function mxDeltaTxt(d){return d>0?'▲'+mxFmt(d):d<0?'▼'+mxFmt(-d):'持平';}
function mxNewDraft(list,today){
  const last=list.length?list[list.length-1]:null;
  return {
    id:null,date:today,total:'',
    full:last?mxStr(last.full):'',
    target:last?mxStr(last.target):'',
    note:'',
    secs:last&&last.sections.length?last.sections.map(s=>({name:s.name,score:'',full:mxStr(s.full)})):[{name:'',score:'',full:''}]
  };
}
function mxEditDraft(e){
  return {id:e.id,date:e.date,total:mxStr(e.total),full:mxStr(e.full),target:mxStr(e.target),note:e.note,
    secs:e.sections.map(s=>({name:s.name,score:mxStr(s.score),full:mxStr(s.full)}))};
}
function mxValidate(d,uidFn){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(String(d.date||'')))return {error:'请选择考试日期'};
  const secs=[];const seen={};
  for(let i=0;i<d.secs.length;i++){
    const r=d.secs[i];
    const name=String(r.name||'').trim(),sc=String(r.score||'').trim(),fu=String(r.full||'').trim();
    if(!name&&!sc&&!fu)continue;
    if(!name)return {error:'第'+(i+1)+'个部分请填写名称'};
    if(seen[name])return {error:'「'+name+'」重复了，各部分名称不能相同'};
    seen[name]=1;
    const s=mxNum(sc);
    if(sc===''||s===null||s<0)return {error:'请填写「'+name+'」的得分（不小于0）'};
    let f=null;
    if(fu!==''){
      f=mxNum(fu);
      if(f===null||f<=0)return {error:'「'+name+'」的满分须大于0'};
      if(s>f)return {error:'「'+name+'」得分不能超过满分'};
    }
    secs.push({name:name,score:s,full:f});
  }
  let total;
  const ts=String(d.total||'').trim();
  if(ts===''){
    if(!secs.length)return {error:'请填写总分'};
    total=Math.round(secs.reduce((a,x)=>a+x.score,0)*100)/100;
  }else{
    total=mxNum(ts);
    if(total===null||total<0)return {error:'总分须是不小于0的数字'};
  }
  let full=null;const fs=String(d.full||'').trim();
  if(fs!==''){
    full=mxNum(fs);
    if(full===null||full<=0)return {error:'总分满分须大于0'};
    if(total>full)return {error:'总分不能超过满分'};
  }
  let target=null;const gs=String(d.target||'').trim();
  if(gs!==''){
    target=mxNum(gs);
    if(target===null||target<=0)return {error:'目标分须大于0'};
  }
  return {rec:{id:d.id||uidFn(),date:d.date,total:total,full:full,target:target,sections:secs,note:String(d.note||'').trim()}};
}

function mxChart(h,vis,selId,target,W,H,pick){
  const L=30,R=8,T=16,B=16,n=vis.length;
  const pw=W-L-R,ph=H-T-B;
  const rd=v=>String(Math.round(v*10)/10);
  const vals=vis.map(e=>e.total);
  if(target!==null)vals.push(target);
  let lo=Math.min.apply(null,vals),hi=Math.max.apply(null,vals);
  if(hi===lo){const p=Math.max(Math.abs(hi)*0.1,5);lo-=p;hi+=p;}
  else{const p=(hi-lo)*0.2;lo-=p;hi+=p;}
  if(lo<0)lo=0;
  const X=i=>n===1?L+pw/2:L+12+(pw-24)*i/(n-1);
  const Y=v=>T+ph*(1-(v-lo)/(hi-lo));
  const step=n>6?Math.ceil(n/5):1;
  const kids=[];
  [lo,(lo+hi)/2,hi].forEach(v=>{
    const y=Y(v);
    kids.push(h('line',{x1:rd(L),y1:rd(y),x2:rd(W-R),y2:rd(y),class:'mx-grid'}));
    kids.push(h('text',{x:rd(L-4),y:rd(y+3),class:'mx-ax','text-anchor':'end'},String(Math.round(v))));
  });
  if(target!==null){
    const yt=Y(target);
    kids.push(h('line',{x1:rd(L),y1:rd(yt),x2:rd(W-R),y2:rd(yt),class:'mx-tgt'}));
    kids.push(h('text',{x:rd(L+3),y:rd(yt-3),class:'mx-tl','text-anchor':'start'},'目标 '+mxFmt(target)));
  }
  const pts=vis.map((e,i)=>rd(X(i))+','+rd(Y(e.total)));
  if(n>1){
    kids.push(h('polygon',{points:pts.join(' ')+' '+rd(X(n-1))+','+rd(T+ph)+' '+rd(X(0))+','+rd(T+ph),class:'mx-area'}));
    kids.push(h('polyline',{points:pts.join(' '),class:'mx-line'}));
  }
  vis.forEach((e,i)=>{
    const x=X(i),y=Y(e.total),sel=e.id===selId;
    kids.push(h('circle',{cx:rd(x),cy:rd(y),r:sel?'5':'3.5',class:'mx-dot'+(sel?' sel':'')}));
    if(n<=6||sel)kids.push(h('text',{x:rd(x),y:rd(y-8),class:'mx-val'+(sel?' sel':''),'text-anchor':'middle'},mxFmt(e.total)));
    if((n-1-i)%step===0)kids.push(h('text',{x:rd(x),y:rd(H-4),class:'mx-ax','text-anchor':'middle'},mxMD(e.date)));
  });
  vis.forEach((e,i)=>{
    kids.push(h('circle',{cx:rd(X(i)),cy:rd(Y(e.total)),r:'12',class:'mx-hit','aria-label':e.date+' 总分 '+mxFmt(e.total),onclick:()=>pick(e.id)}));
  });
  return h('svg',{viewBox:'0 0 '+W+' '+H,class:'mx-chart',role:'img','aria-label':'总分变化趋势'},kids);
}

function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day,size}=ctx;
  const h=mxH(el);
  const sz=String(size||root.dataset.size||'3x3');
  const wide=sz.charAt(0)==='6',tall=sz.charAt(2)==='6';
  const list=mxExams(state);
  const cur=mxSel(list,ui.sel);
  const go=patch=>{Object.assign(ui,patch);redraw();};
  const lim=ui.n===undefined?5:ui.n;
  const vis=lim>0?list.slice(-lim):list;
  const dims=sz==='3x3'?[172,70]:sz==='6x3'?[258,112]:sz==='3x6'?[172,130]:[384,150];

  function addBtn(){
    return h('button',{class:'mx-btn pri mx-add',type:'button','aria-label':'记一次模考成绩',
      onclick:()=>go({view:'edit',draft:mxNewDraft(list,day()),err:'',saving:false,focus:'total'})},
      h('span',{class:'mx-plus'},'＋'),h('span',{class:'mx-add-t'},' 记一次'));
  }
  function chipsFor(e,prev,prevLabel){
    const out=[];
    if(e.target!==null){
      const g=e.total-e.target;
      out.push(h('span',{class:'mx-chip'+(g>=0?' ok':'')},g>=0?'已达目标 +'+mxFmt(g):'距目标 '+mxFmt(-g)));
    }else out.push(h('span',{class:'mx-chip mute'},'未设目标'));
    if(prev)out.push(h('span',{class:'mx-chip'},prevLabel+' '+mxDeltaTxt(e.total-prev.total)));
    else out.push(h('span',{class:'mx-chip mute'},'首次记录'));
    return out;
  }
  function head(){
    const last=list[list.length-1],prev=list[list.length-2]||null;
    return h('div',{class:'mx-head'},
      h('div',{class:'mx-val-box'},
        h('span',{class:'mx-big'},mxFmt(last.total)),
        last.full!==null?h('span',{class:'mx-of'},'/'+mxFmt(last.full)):null,
        h('span',{class:'mx-date'},h('span',{class:'mx-lbl'},'最近 '),mxMD(last.date))),
      h('div',{class:'mx-meta'},chipsFor(last,prev,'较上次')),
      addBtn());
  }
  function stepper(withRange){
    const i=list.findIndex(e=>e.id===cur.id);
    const nb=(dir,txt,label)=>h('button',{class:'mx-nav',type:'button','aria-label':label,disabled:!list[i+dir],onclick:()=>go({sel:list[i+dir].id})},txt);
    const many=list.length>1;
    const rlabel=lim===5?'近5次':lim===10?'近10次':'全部';
    let right=null;
